`timescale 1ns/1ps
// @latency 1
module priority_encoder8_core (
    input wire clk,
    input wire rst,
    input wire [7:0] request,
    output wire [2:0] index,
    output wire valid
);

reg [2:0] index_q;
reg valid_q;

assign index = index_q;
assign valid = valid_q;

always @(posedge clk) begin
    if (rst) begin
        index_q <= 3'd0;
        valid_q <= 1'b0;
    end else begin
        valid_q <= |request;
        if (request[7])
            index_q <= 3'd7;
        else if (request[6])
            index_q <= 3'd6;
        else if (request[5])
            index_q <= 3'd5;
        else if (request[4])
            index_q <= 3'd4;
        else if (request[3])
            index_q <= 3'd3;
        else if (request[2])
            index_q <= 3'd2;
        else if (request[1])
            index_q <= 3'd1;
        else
            index_q <= 3'd0;
    end
end

endmodule
